$messageConfirmation=$_SESSION['reservation_confirmation']??'';unset($_SESSION['reservation_confirmation']);$messageErreur='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!bocalChatCsrfValid())throw new InvalidArgumentException('La page a expiré. Réessayez avec le formulaire ci-dessous.');
  if(bocalChatPostText('website')!=='')throw new InvalidArgumentException('L’envoi n’a pas abouti.');
