  $people=filter_var(bocalChatPostText('nb_personnes'),FILTER_VALIDATE_INT);$table=filter_var(bocalChatPostText('table_id'),FILTER_VALIDATE_INT);
  if($nom===''||strlen($nom)>150||!preg_match('/^[+0-9(). \-]{6,30}$/',$telephone))throw new InvalidArgumentException('Vérifiez votre nom et votre numéro de téléphone.');
  if($email!==''&&(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>254))throw new InvalidArgumentException('Vérifiez votre adresse e-mail.');
  if(!$people||$people<1||$people>30||!$table||$table<1||$table>18)throw new InvalidArgumentException('Indiquez le nombre de personnes et choisissez une table sur le plan.');
  if(strlen($message)>2000)throw new InvalidArgumentException('Votre message est trop long (2 000 caractères maximum).');
  [$start,$end]=bocalSlot($date,$heure);
  if(!bocalRateTake('reservation',[3600=>5,86400=>15]))throw new InvalidArgumentException('Plusieurs demandes ont déjà été envoyées. Appelez l’équipe pour poursuivre.');
  require __DIR__.'/includes/db.php';bocalTablesEnsure($pdo);$pdo->beginTransaction();bocalTableLock($pdo,1);
  if(bocalUnassigned($pdo,$start,$end))throw new RuntimeException('L’équipe finalise le placement sur ce créneau. Choisissez un autre moment ou appelez-nous.');
  $t=bocalTableLock($pdo,$table);
  if(!(int)$t['enabled']||(int)$t['seats']<$people||bocalTableConflict($pdo,$table,$start,$end))throw new RuntimeException('Cette table vient de devenir indisponible ou ne convient pas au groupe. Choisissez-en une autre sur le plan.');
  $q=$pdo->prepare('INSERT INTO reservations (nom,telephone,email,date_reservation,heure_reservation,nb_personnes,message,statut) VALUES (?,?,?,?,?,?,?,?)');$q->execute([$nom,$telephone,$email,$date,$heure,$people,$message,'en_attente']);$id=(int)$pdo->lastInsertId();
  $q=$pdo->prepare('INSERT INTO bocal_table_bookings (reservation_id,table_id,start_at,end_at) VALUES (?,?,?,?)');$q->execute([$id,$table,$start,$end]);$pdo->commit();
  $_SESSION['reservation_confirmation']='Votre demande pour la table '.$table.' le '.date('d/m/Y',strtotime($date)).' à '.$heure.' a été envoyée. L’équipe doit encore la confirmer.';$_SESSION['csrf_token']=bin2hex(random_bytes(32));header('Location: reservation.php');exit;
 }catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$messageErreur=$e instanceof PDOException?'L’envoi est momentanément indisponible. Appelez le 03 29 75 95 50.':$e->getMessage();}
}
